from tools.run_evidence import EvidenceResult
class Demonstration(unittest.TestCase):
 def test_failure(self):self.fail('authored failure')
 def test_error(self):raise ValueError('authored error')
 def test_subtest(self):
  with self.subTest(authored=True):self.fail('authored subtest')
runner=unittest.TextTestRunner(stream=io.StringIO(),resultclass=EvidenceResult,verbosity=0)
